def maxArea(height):
    left, right = 0, len(height) - 1
    max_water = 0
    while left < right:
        cur = (right - left) * min(height[left], height[right])
        if cur > max_water:
            max_water = cur
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return max_water

