public class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxWater = 0;
        while (left < right) {
            int cur = (right - left) * Math.min(height[left], height[right]);
            if (cur > maxWater) maxWater = cur;
            if (height[left] < height[right]) left++;
            else right--;
        }
        return maxWater;
    }
}

